class Solution {
    public double trimMean(int[] arr){
        Arrays.sort(arr);
        int trim=arr.length/20;
        double sum=0;
        for(int i=trim;i<arr.length-trim;i++)sum+=arr[i];
        return sum/(arr.length-2*trim);
    }
}

code.kotlin:
class Solution {
    fun trimMean(arr:IntArray):Double{
        arr.sort();
        val trim=arr.size/20;
        var sum=0.0;
        for(i in trim until arr.size-trim)sum+=arr[i];
        return sum/(arr.size-2*trim)
    }
}

code.cpp:
class Solution {
    public: double trimMean(vector<int>& arr){
        sort(arr.begin(),arr.end());
        int trim=arr.size()/20;
        double sum=accumulate(arr.begin()+trim,arr.end()-trim,0.0);
        return sum/(arr.size()-2*trim);
    }
};
